import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val str = scanner.next()
    var t = 0
    var valid = true
    for (c in str) {
        val diff = c - 'a'
        if (diff > t) {
            valid = false
            break
        }
        if (diff == t) {
            t++
        }
    }
    println(if (valid) "YES" else "NO")
}

